#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

#define MIN(a,b) (a) < (b) ? (a) : (b)

typedef struct ListNode {
    int ele;
    struct ListNode *next;
} ListNode;

typedef struct LinkedList {
    int size;
    ListNode *head;
    ListNode *tail;
} LinkedList;

LinkedList *new_LinkedList();
void addLast_LinkedList(LinkedList *link, int ele);

void dfs(int arr[], int index, int level, int sum, LinkedList *res);
int getResult(int arr[]);

int main() {
    int arr[10];
    for (int i = 0; i < 10; i++) {
        scanf("%d", &arr[i]);
    }

    printf("%d\n", getResult(arr));

    return 0;
}

int cmp(const void *a, const void *b) {
    return (*(int *) a) - (*(int *) b);
}

int getResult(int arr[]) {
    qsort(arr, 10, sizeof(int), cmp);

    LinkedList *res = new_LinkedList();
    // dfs求10选5的去重组合，并将组合之和记录进res中，即res中记录的是所有可能性的5人小队实力值之和
    dfs(arr, 0, 0, 0, res);

    int sum = 0;
    for (int i = 0; i < 10; i++) sum += arr[i];

    int ans = INT_MAX;

    // 某队实力为subSum，则另一队实力为sum - subSum，则两队实力差为 abs((sum - subSum) - subSum)，先求最小实力差
    ListNode *cur = res->head;
    while (cur != NULL) {
        ans = MIN(ans, abs(sum - 2 * cur->ele));
        cur = cur->next;
    }

    return ans;
}

// 求解去重组合
void dfs(int arr[], int index, int level, int sum, LinkedList *res) {
    if (level == 5) {
        addLast_LinkedList(res, sum);
        return;
    }

    for (int i = index; i < 10; i++) {
        if (i > index && arr[i] == arr[i - 1]) continue; // arr已经升序，这里进行树层去重
        dfs(arr, i + 1, level + 1, sum + arr[i], res);
    }

}

LinkedList *new_LinkedList() {
    LinkedList *link = (LinkedList *) malloc(sizeof(LinkedList));

    link->size = 0;
    link->head = NULL;
    link->tail = NULL;

    return link;
}

void addLast_LinkedList(LinkedList *link, int ele) {
    ListNode *node = (ListNode *) malloc(sizeof(ListNode));

    node->ele = ele;
    node->next = NULL;

    if (link->size == 0) {
        link->head = node;
        link->tail = node;
    } else {
        link->tail->next = node;
        link->tail = node;
    }

    link->size++;
}
